import * as T from '../vendor/three.module.js';
// Cut only the small region covering the actor. Instanced trim follows the same
// world-space mask as masonry; whole wall segments never disappear independently.
export function createPlayerCutaway(world){
 const uniforms={playerCutCenter:{value:new T.Vector3()},playerCutDirection:{value:new T.Vector3()},playerCutEnabled:{value:0}},seen=new WeakSet(),ray=new T.Raycaster(),direction=new T.Vector3(),rayDirection=new T.Vector3(),target=new T.Vector3(),offsets=[[0,0],[-.6,0],[.6,0],[0,.8],[0,-.65]],hits=[],visible=[],meshes=[],roots=[],rootCounts=[];let stamp=-1,lastProbe=-1,occluded=false,listedAt=-Infinity;
 function install(material){if(!material||seen.has(material))return;seen.add(material);const before=material.onBeforeCompile,key=material.customProgramCacheKey?.bind(material);material.onBeforeCompile=function(shader,renderer){before?.call(this,shader,renderer);if(shader.uniforms.playerCutEnabled)return;Object.assign(shader.uniforms,uniforms);shader.vertexShader='varying vec3 vPlayerCutWorld;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <worldpos_vertex>','#include <worldpos_vertex>\nvec4 cutPosition=vec4(transformed,1.0);\n#ifdef USE_INSTANCING\ncutPosition=instanceMatrix*cutPosition;\n#endif\nvPlayerCutWorld=(modelMatrix*cutPosition).xyz;');shader.fragmentShader='varying vec3 vPlayerCutWorld;\nuniform vec3 playerCutCenter;\nuniform vec3 playerCutDirection;\nuniform float playerCutEnabled;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <dithering_fragment>','vec3 cutDelta=vPlayerCutWorld-playerCutCenter;\nfloat cutAlong=dot(cutDelta,playerCutDirection);\nif(playerCutEnabled>0.5 && cutAlong < -0.6 && length(cutDelta-playerCutDirection*cutAlong)<2.2 && mod(floor(gl_FragCoord.x)+floor(gl_FragCoord.y),4.0)>0.5) discard;\n#include <dithering_fragment>');};material.customProgramCacheKey=()=>String(key?.()||'')+'|player-cutaway-1';material.needsUpdate=true;}
 function eligible(o){if(!o.isMesh)return false;for(let p=o;p;p=p.parent)if(!p.visible||p.userData.visualEffect||p.userData.protectorBeam||p.userData.battleProtectorBeam)return false;return true;}
 // Mesh candidates under the castles and arena are cached; the list is rebuilt when a root's child count changes,
 // when a cached mesh was detached, or every 2 s. Every 0.25 s only meshes whose materials lack the cut are checked.
 function list(time){roots.length=rootCounts.length=meshes.length=0;for(const root of world.castles)roots.push(root);if(world.arena)roots.push(world.arena);for(const root of roots){rootCounts.push(root.children.length);root.traverse(o=>{if(o.isMesh)meshes.push(o);});}listedAt=time;}
 function changed(time){if(time-listedAt>2||time<listedAt||roots.length!==world.castles.length+(world.arena?1:0))return true;for(let i=0;i<roots.length;i++){const root=i<world.castles.length?world.castles[i]:world.arena;if(roots[i]!==root||root.children.length!==rootCounts[i])return true;}return false;}
 function pending(o){const m=o.material;if(!Array.isArray(m))return !!m&&!seen.has(m);for(const x of m)if(x&&!seen.has(x))return true;return false;}
 function cover(o){if(o.isMesh&&pending(o)&&eligible(o))for(const m of Array.isArray(o.material)?o.material:[o.material])install(m);}
 function sweep(){let detached=false;for(const o of meshes){if(!o.parent){detached=true;continue;}cover(o);}return detached;}
 function update(camera,center,enabled,time=0){
  uniforms.playerCutCenter.value.copy(center);uniforms.playerCutDirection.value.copy(center).sub(camera.position).normalize();uniforms.playerCutEnabled.value=enabled?1:0;
  if(time-stamp>.25||time<stamp){stamp=time;for(const o of world.occluders)cover(o);if(changed(time))list(time);if(sweep()){list(time);sweep();}}
  if(!enabled){occluded=false;return false;}if(time>=lastProbe&&time-lastProbe<.1)return occluded;lastProbe=time;occluded=false;visible.length=0;for(const o of world.occluders)if(!o.isInstancedMesh&&eligible(o))visible.push(o);for(let i=0;i<offsets.length;i++){const offset=offsets[i];target.copy(center);target.x+=offset[0];target.y+=offset[1];direction.copy(target).sub(camera.position);ray.set(camera.position,rayDirection.copy(direction).normalize());ray.far=direction.length()-.6;hits.length=0;if(ray.intersectObjects(visible,false,hits).length){occluded=true;return true;}}return false;
 }
 return {update,uniforms,install};
}
